        'guide.wizard.step': 'Étape {current} / {total}',
        'guide.wizard.next': 'Suivant',
        'guide.wizard.finish': 'Terminer la visite',
        'guide.wizard.welcome.title': 'Bienvenue dans Actor Empire',
        'guide.wizard.welcome.body': 'Vous construisez une vie, pas seulement une course au prochain rôle. Les meilleures sauvegardes équilibrent carrière, argent, célébrité, relations, puissance de studio et planification long terme.',
        'guide.wizard.weeklyLoop.title': 'Votre boucle hebdomadaire',
        'guide.wizard.weeklyLoop.body': 'Chaque semaine est un puzzle de ressources. Dépensez votre énergie dans le jeu d’acteur, la croissance sociale, les affaires ou la vie personnelle, puis avancez l’âge pour voir les résultats.',
        'guide.wizard.career.title': 'Construire d’abord la carrière',
        'guide.wizard.career.body': 'CastLink, les répétitions, de meilleurs agents et de solides performances ouvrent l’échelle du divertissement. Au début, le travail régulier et les bons choix de rôle comptent plus que la chasse aux projets géants.',
        'guide.wizard.stats.title': 'Comprendre chaque statistique',
        'guide.wizard.stats.body': 'La célébrité augmente votre profil. La réputation renforce la confiance. Les abonnés améliorent la portée. L’argent donne des options. Aucun ne remplace totalement les autres.',
        'guide.wizard.business.title': 'Les affaires demandent de la gestion',
        'guide.wizard.business.body': 'Les affaires ne produisent pas de l’argent toutes seules. Prix, hype, personnel, stock et expansion comptent tous.',
        'guide.wizard.studio.title': 'La maison de production se joue sur le long terme',
        'guide.wizard.studio.body': 'Votre studio brille quand vous développez de bons projets, gérez les sorties et transformez les succès en catalogue. Les gros gains peuvent prendre du temps.',
        'guide.wizard.stories.title': 'Les histoires connectées demandent du soin',
        'guide.wizard.stories.body': 'Les franchises et univers sont puissants parce que personnages, casting, suites, crossovers et mémoire du marché continuent d’avancer.',
        'guide.handbook.title': 'Manuel',
        'guide.handbook.subtitle': 'Une référence claire sur le fonctionnement du jeu, le rôle de chaque système et le moment où il faut s’en soucier.',
        'guide.handbook.gettingStarted.title': 'Bien démarrer',
        'guide.handbook.gettingStarted.p1': 'Votre premier objectif est un élan fiable. Au départ, de petites victoires en auditions, activité sociale et gestion d’argent battent souvent les paris risqués.',
        'guide.handbook.gettingStarted.p2': 'Pensez semaine par semaine. Chaque décision consomme temps et énergie, et trop vous disperser ralentit toute progression.',
        'guide.handbook.gettingStarted.p3': 'Utilisez souvent les apps du téléphone. CastLink développe la carrière, Équipe gère les contrats, les réseaux construisent la portée et le Guide explique le reste.',
        'guide.handbook.stats.title': 'Statistiques expliquées',
        'guide.handbook.stats.p1': 'La célébrité est votre profil public. Elle aide à être vu, obtenir de plus grandes opportunités et rester culturellement pertinent.',
        'guide.handbook.stats.p2': 'La réputation montre à quel point l’industrie vous prend au sérieux. Une forte réputation soutient la confiance et de meilleurs résultats long terme.',
        'guide.handbook.stats.p3': 'Les abonnés représentent votre portée sociale. Ils aident l’influence, les sponsors et la croissance en ligne, mais ne portent pas seuls une carrière d’acteur.',
        'guide.handbook.stats.p4': 'L’humeur et l’énergie déterminent ce que vous pouvez faire. Un gros compte bancaire vaut moins si votre personnage est épuisé ou malheureux.',
        'guide.handbook.career.title': 'Parcours de carrière',
        'guide.handbook.career.p1': 'CastLink est le principal endroit pour trouver du travail. Talent, préparation, expérience et représentation améliorent la qualité des rôles accessibles.',
        'guide.handbook.career.p2': 'La préparation compte. Les répétitions et les bons choix de rôle rendent les performances plus régulières.',
        'guide.handbook.career.p3': 'Le début construit un palmarès, le milieu construit l’élan, et la fin tourne autour du levier, du choix et de l’héritage.',
        'guide.handbook.weeklyLoop.title': 'Boucle hebdomadaire et énergie',
        'guide.handbook.weeklyLoop.p1': 'L’énergie est le carburant hebdomadaire. Acting, actions sociales, affaires et vie personnelle y puisent tous.',
        'guide.handbook.weeklyLoop.p2': 'Ne gaspillez pas les semaines vides. Si vous attendez un projet, développez célébrité, relations, compétences ou progression business.',
        'guide.handbook.weeklyLoop.p3': 'La récupération a de la valeur. Parfois, remettre votre personnage d’aplomb rend les semaines suivantes plus fortes.',
        'guide.handbook.social.title': 'Fame, abonnés et réseaux',
        'guide.handbook.social.p1': 'Les réseaux sociaux vous gardent visible et peuvent soutenir votre carrière globale dans le divertissement.',
        'guide.handbook.social.p2': 'Chaque plateforme a son rôle : image, portée, conversation et monétisation.',
        'guide.handbook.social.p3': 'Utilisez les réseaux avec intention. Chaque post n’a pas besoin de chercher la viralité.',
        'guide.handbook.relationships.title': 'Relations et réseau',
        'guide.handbook.relationships.p1': 'Les relations professionnelles peuvent changer la qualité des opportunités visibles.',
        'guide.handbook.relationships.p2': 'Les relations personnelles ne sont pas qu’un décor. La négligence peut créer du drama, tandis que des liens sains soutiennent une meilleure trajectoire.',
        'guide.handbook.relationships.p3': 'Le networking fonctionne mieux dans la durée. L’effort répété bat souvent un seul geste coûteux.',
        'guide.handbook.businesses.title': 'Affaires',
        'guide.handbook.businesses.p1': 'Les affaires sont des moteurs de revenus long terme. Certaines sont des services stables, tandis que les produits récompensent une gestion active.',
        'guide.handbook.businesses.p2': 'Prix, qualité, hype, personnel, stock et expansion comptent tous.',
        'guide.handbook.businesses.p3': 'Le marketing fonctionne mieux quand produit, capacité et organisation sont déjà solides.',
        'guide.handbook.productionHouse.title': 'Maison de production',
        'guide.handbook.productionHouse.p1': 'Pensez par étapes : développement, production, sortie et après-vie comptent tous.',
        'guide.handbook.productionHouse.p2': 'Tous les projets ne doivent pas être précipités. Une meilleure planification peut battre une sortie forcée.',
        'guide.handbook.productionHouse.p3': 'Votre bibliothèque compte. Avec le temps, le studio gagne en valeur quand vous construisez un catalogue plutôt que de dépendre d’un seul hit.',
        'guide.handbook.developmentLab.title': 'Laboratoire de développement',
        'guide.handbook.developmentLab.p1': 'Le Coffre garde scripts et concepts jusqu’à ce que vous soyez prêt à les développer, vendre ou produire.',
        'guide.handbook.developmentLab.p2': 'Idée permet de façonner genre, ton, audience et identité de l’histoire.',
        'guide.handbook.developmentLab.p3': 'Le Marché permet d’acheter ou découvrir des scripts. Surveillez format, genre, qualité et tout sujet connu ou accroche de franchise.',
        'guide.handbook.developmentLab.noteTitle': 'Pas de formule exacte',
        'guide.handbook.developmentLab.noteBody': 'Le guide explique ce qui compte, pas les calculs cachés. Les bons concepts viennent souvent du fit, de la clarté et du timing.',
        'developmentLab.title': 'Laboratoire de développement',
