        'guide.handbook.scriptFormats.title': 'Scripts, genres et formats',
        'guide.handbook.scriptFormats.p1': 'Le format est la forme de production : film, série, prise de vue réelle, long-métrage animé, film anime, etc.',
        'guide.handbook.scriptFormats.p2': 'Le genre est la promesse faite au public : drame, action, biopic, sport, documentaire, comédie musicale, animation, anime ou autres voies proches.',
        'guide.handbook.scriptFormats.p3': 'Le genre principal porte l’identité centrale. Le genre secondaire ajoute une saveur et doit soutenir le projet.',
        'guide.handbook.scriptFormats.tag1': 'Format = emballage',
        'guide.handbook.scriptFormats.tag2': 'Genre = promesse',
        'guide.handbook.scriptFormats.tag3': 'Ton = sensation',
        'guide.handbook.scriptFormats.tag4': 'Public = portée',
        'guide.handbook.greenlight.title': 'Flux de greenlight',
        'guide.handbook.greenlight.p1': 'Le greenlight transforme un script en plan de production avec réalisateur, casting, équipe, matériel, lieux, ton et package final.',
        'guide.handbook.greenlight.p2': 'Le budget n’est pas qu’un chiffre. Cachets, qualité de l’équipe, choix de production, personnages connus et échelle le font bouger.',
        'guide.handbook.greenlight.p3': 'La négociation compte. Le casting de retour et les grands noms peuvent être puissants, mais ils ont toujours besoin d’accords.',
        'guide.handbook.greenlight.b1': 'Utilisez l’étape casting pour verrouiller qui joue chaque rôle.',
        'guide.handbook.greenlight.b2': 'Utilisez les personnages connectés quand l’histoire appartient à une franchise ou un univers.',
        'guide.handbook.greenlight.b3': 'Utilisez l’étape de revue pour repérer les faiblesses avant de vous engager.',
