        'x.timelineForecastSub': 'X est volatile. Les petits comptes peuvent encore être découverts, mais le heat peut se répandre sur la réputation et les futurs événements.',
        'services.x.generalPost': 'Je viens de boire le meilleur café de ma vie. || Quelqu’un d’autre sent que cette journée va être excellente ? || Lecture de scripts toute la journée. || Le trafic de LA est presque un trait de personnalité maintenant. || La vie sur plateau, c’est la meilleure vie. || Le cinéma est de retour. || Je viens de voir un chef-d’œuvre. Pas de spoilers.',
        'services.x.newsPost': 'DERNIÈRE MINUTE : des dirigeants de studio laissent entendre une énorme fusion. || Update box-office : les chiffres semblent solides pour la sélection estivale. || La rumeur dit qu’une certaine star A-list quitte sa franchise. || Les plateformes streaming annoncent encore des hausses de prix. || Les prédictions de saison des prix chauffent déjà.',
        'services.x.universePost': 'Je le dis maintenant, le prochain film {universeName} va battre des records. || Qui d’autre reste debout jusqu’à 3h du matin pour voir le nouveau trailer {universeName} ? || S’ils ne ramènent pas le casting original pour {universeName}, on se révolte. || On peut parler de la scène post-générique du dernier film {universeName} ? || Le casting du nouveau méchant de {universeName} est absolument parfait.',
