        'services.npcVenture.launch.headline': '{Owner} launches {Venture}, a new {Archetype} with serious industry ambitions. || New Player: {Owner}-backed {Venture} enters the production race. || {Venture} opens its doors as {Owner} makes a bigger bet on ownership. || Industry Watch: {Owner} quietly builds {Venture} into a new Hollywood vehicle.',
        'services.npcVenture.launch.subtext': '{ventureName} begins with roughly ${capital}M in launch capital.',
        'services.npcVenture.development.headline': '{Venture} is packaging {Title}, with insiders calling it a calculated swing. || {Venture} begins development on {Title} as rivals watch the newcomer closely. || {Owner}\'s {Venture} starts chasing talent for {Title}. || Bidding chatter builds around {Title}, the latest move from {Venture}.',
        'services.npcVenture.development.subtext': '{ventureName} is still building its slate.',
        'services.npcVenture.hit.headline': '{Venture} scores a breakout hit with {Title}. || {Title} turns {Venture} from vanity project into real contender. || Industry Surprise: {Venture} lands a major win with {Title}. || {Owner}\'s ownership gamble pays off as {Title} overperforms.',
        'services.npcVenture.hit.subtext': 'Starring {leadActorName}. Directed by {directorName}.',
        'services.npcVenture.flop.headline': '{Venture} takes a costly hit after {Title} misses expectations. || {Title} stumbles, putting pressure on {Owner}\'s {Venture}. || Rough Week: {Venture} faces questions after {Title} underperforms. || Insiders wonder if {Venture} moved too fast after {Title} flops.',
        'services.npcVenture.flop.subtext': 'The miss cut into {ventureName}\'s cash reserves.',
        'services.npcVenture.closure.headline': '{Venture} shuts down after a difficult run of projects. || {Owner} closes {Venture} as losses mount. || End of the Line: {Venture} quietly winds down operations. || {Venture} exits the market after failing to build sustainable momentum.',
        'services.npcVenture.closure.reason.cash': 'Cash reserves collapsed.',
        'services.npcVenture.closure.reason.slate': 'The slate failed to gain traction.',
        'services.npcVenture.log.launch': '{ownerName} launched {ventureName}.',
        'services.npcVenture.log.closure': '{ventureName} closed after {count} releases.',
        'services.npcVenture.log.offer': '📩 {ventureName} sent you a role offer.',
        'services.npcVenture.project.type.movie': 'film',
        'services.npcVenture.project.type.series': 'series',
        'services.npcVenture.project.description': '{ventureName} is producing a {genre} {projectType} backed by {ownerName}.',
        'services.npcVenture.offer.intro': 'We are putting together a focused package and think you fit the role. || This is a leaner project, but the team believes it can travel. || Our studio is moving fast and wants you attached before the town catches up. || We are building the next slate around talent with heat, and your name came up.',
        'services.npcVenture.offer.text': '{intro}\n\nProject: {projectName}\nStudio: {studioName}\nFounder: {founderName}\nRole: {roleType}\nEstimated pay: ${estimatedPay}\n\nThis is a real company in the market now. If the project hits, the studio gains momentum. If it misses, the risk is on them.',
